-- Errata reading for H10: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH women AS MATERIALIZED ( SELECT id AS patient FROM patients WHERE json_extract(payload,'$.sex_reported')='F' AND json_type(payload,'$.age_reported')='integer' AND coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=patients.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(payload,'$.age_reported')) BETWEEN 18 AND 44 ), hgb AS MATERIALIZED ( SELECT patient,json_extract(payload,'$.value') AS v FROM records WHERE stream='labs' AND json_extract(payload,'$.name') IN ('Hemoglobin','Hgb') AND json_extract(payload,'$.unit')='g/dL' AND json_type(payload,'$.value') IN ('integer','real') ) SELECT COUNT(DISTINCT women.patient) AS count FROM women JOIN hgb USING(patient) WHERE hgb.v<10;
